item.aggregated_output:
To get started with GitHub CLI, please run:  gh auth login
Alternatively, populate the GH_TOKEN environment variable with a GitHub API authentication token.
name: CI

on:
  push:
    branches: [main]
  pull_request:
  workflow_dispatch:

permissions:
  contents: read

jobs:
  check:
    name: typecheck + unit tests + build
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 20
          cache: npm
      - run: npm ci
      - run: npm run check
      - run: node --check dist/extension.js && node --check dist/extension.core.js

  package:
    name: package VSIX (windows)
    runs-on: windows-latest
    needs: check
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 20
          cache: npm
      - run: npm ci
      - run: npm run build

      # dist/node_modules, dist/i18n, workers and wasm files are not in git; they are taken
      # from the newest published release VSIX. Without one the packaging steps are skipped.
      - name: Fetch runtime assets from the latest release
        id: assets
        shell: pwsh
        env:
          GH_TOKEN: ${{ github.token }}
        run: |
          New-Item -ItemType Directory -Force -Path .tmp/release-assets | Out-Null
          gh release download --repo $env:GITHUB_REPOSITORY --pattern '*.vsix' --dir .tmp/release-assets
          $vsix = Get-ChildItem .tmp/release-assets -Filter *.vsix | Sort-Object LastWriteTime | Select-Object -Last 1
          if ($vsix) {
            node scripts/restore-dist-assets.mjs --from $vsix.FullName
            "found=true" | Out-File -FilePath $env:GITHUB_OUTPUT -Append
          } else {
            Write-Host "no release VSIX found; skipping packaging"
            "found=false" | Out-File -FilePath $env:GITHUB_OUTPUT -Append
          }
        continue-on-error: true

      - name: Package VSIX
        if: steps.assets.outputs.found == 'true'
        shell: pwsh
        run: powershell -ExecutionPolicy Bypass -File scripts/package-vsix.ps1

      - name: Verify package
        if: steps.assets.outputs.found == 'true'
        shell: pwsh
        run: powershell -ExecutionPolicy Bypass -File scripts/verify-package.ps1

      - name: SHA256
        if: steps.assets.outputs.found == 'true'
        shell: pwsh
        run: |
          Get-ChildItem release -Filter *.vsix | ForEach-Object {
            $hash = (Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLower()
            "$hash  $($_.Name)" | Out-File -FilePath "$($_.FullName).sha256" -Encoding ascii
            Write-Host "$hash  $($_.Name)"
          }

      - name: Upload VSIX
        if: steps.assets.outputs.found == 'true'
        uses: actions/upload-artifact@v4
        with:
          name: vibe-code-vsix
          path: |
            release/*.vsix
            release/*.sha256
          if-no-files-found: error
// Builds dist/extension.js from src/ and stages the vendored core bundle next to it.
//
//   dist/extension.js       <- esbuild bundle of src/extension.ts (this repo's own code)
//   dist/extension.core.js  <- copy of vendor/extension.core.js (upstream Roo-Code core + hooks)
//
// dist/ is never wiped: dist/node_modules, dist/i18n, *.wasm and dist/workers are runtime
// assets that ship with the VSIX and are not produced by this build.
import { build, context } from "esbuild";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const watch = process.argv.includes("--watch");
const distDir = path.join(root, "dist");
const vendorCore = path.join(root, "vendor", "extension.core.js");
const distCore = path.join(distDir, "extension.core.js");

fs.mkdirSync(distDir, { recursive: true });

if (!fs.existsSync(vendorCore)) {
	console.error(`vendor core bundle not found: ${vendorCore}`);
	process.exit(1);
}

function stageCore() {
	const src = fs.statSync(vendorCore);
	const same = fs.existsSync(distCore) && fs.statSync(distCore).size === src.size && fs.statSync(distCore).mtimeMs >= src.mtimeMs;
	if (!same) {
		fs.copyFileSync(vendorCore, distCore);
		console.log(`staged ${path.relative(root, distCore)} (${(src.size / 1024 / 1024).toFixed(1)} MB)`);
	}
}

function warnMissingRuntimeAssets() {
	const required = ["node_modules", "i18n", "workers", "tree-sitter.wasm", "tiktoken_bg.wasm"];
	const missing = required.filter((name) => !fs.existsSync(path.join(distDir, name)));
	if (missing.length > 0) {
		console.warn(`warning: dist/ is missing runtime assets: ${missing.join(", ")}`);
		console.warn("         copy them from an existing release VSIX (extension/dist/) before packaging.");
	}
}

const options = {
	entryPoints: [path.join(root, "src", "extension.ts")],
	outfile: path.join(distDir, "extension.js"),
	bundle: true,
	platform: "node",
	target: "node20",
	format: "cjs",
	// vscode is provided by the extension host; adm-zip is optional at runtime;
	// the core bundle is loaded from the same directory at runtime.
	external: ["vscode", "adm-zip", "./extension.core.js"],
	sourcemap: watch ? "inline" : false,
	legalComments: "none",
	logLevel: "info",
	banner: {
		js: "/* vibe-code: built from src/ by scripts/build.mjs. Core runtime lives in ./extension.core.js (see vendor/PATCHES.md). */",
	},
};

stageCore();
warnMissingRuntimeAssets();

if (watch) {
	const ctx = await context(options);
	await ctx.watch();
	console.log("watching src/ ...");
} else {
	await build(options);
}
param(
	[string]$OutDir = "release",
	[switch]$Lean = $false
)

$ErrorActionPreference = "Stop"
$utf8NoBom = [System.Text.UTF8Encoding]::new($false)

function Escape-Xml([object]$Value) {
	if ($null -eq $Value) {
		return ""
	}

	return [System.Security.SecurityElement]::Escape([string]$Value)
}

function Assert-ChildPath([string]$Parent, [string]$Child) {
	$parentFull = [System.IO.Path]::GetFullPath($Parent).TrimEnd('\', '/')
	$childFull = [System.IO.Path]::GetFullPath($Child)
	if (-not $childFull.StartsWith($parentFull, [System.StringComparison]::OrdinalIgnoreCase)) {
		throw "Refusing to operate outside expected directory: $childFull"
	}
}

$root = [System.IO.Path]::GetFullPath((Join-Path $PSScriptRoot ".."))
$packagePath = Join-Path $root "package.json"
$package = Get-Content -LiteralPath $packagePath -Raw -Encoding UTF8 | ConvertFrom-Json

$outDirFull = [System.IO.Path]::GetFullPath((Join-Path $root $OutDir))
Assert-ChildPath $root $outDirFull
New-Item -ItemType Directory -Path $outDirFull -Force | Out-Null

$stageRoot = Join-Path "C:\tmp" "vibe-code-vsix-stage"
Assert-ChildPath "C:\tmp" $stageRoot
if (Test-Path -LiteralPath $stageRoot) {
	Remove-Item -LiteralPath $stageRoot -Recurse -Force
}

New-Item -ItemType Directory -Path $stageRoot -Force | Out-Null
$extensionDir = Join-Path $stageRoot "extension"
New-Item -ItemType Directory -Path $extensionDir -Force | Out-Null

$directories = @("assets", "dist", "docs", "integrations", "scripts", "tests", "webview-ui")
foreach ($directory in $directories) {
	Copy-Item -LiteralPath (Join-Path $root $directory) -Destination $extensionDir -Recurse -Force
}

$files = @("package.json", "package.nls.json", "package.nls.ko.json", "readme.md", "readme.ko.md", "changelog.md", "LICENSE.txt")
foreach ($file in $files) {
	Copy-Item -LiteralPath (Join-Path $root $file) -Destination $extensionDir -Force
}

$temporaryFiles = Get-ChildItem -LiteralPath $extensionDir -Recurse -Force -File |
	Where-Object {
		$_.Name -like "*.bak-rewrite" -or
		$_.Name -like "*.tmp" -or
		$_.Name -like "*.tmp-rewrite"
	}
if ($temporaryFiles) {
	foreach ($temporaryFile in $temporaryFiles) {
		[System.IO.File]::Delete($temporaryFile.FullName)
	}
}

# Slim node_modules — remove docs, type defs, source maps, and test directories.
# These are not loaded at runtime and only inflate the VSIX.
$slimNodeModules = Join-Path $extensionDir "dist\node_modules"
if (Test-Path -LiteralPath $slimNodeModules) {
	$slimPatterns = @("*.md", "*.markdown", "*.d.ts", "*.ts", "*.map", "LICENSE", "LICENSE.*", "README", "README.*", "CHANGELOG", "CHANGELOG.*", "HISTORY", "HISTORY.*", ".npmignore", ".eslintrc*", ".prettierrc*", "*.test.js", "*.spec.js")
	foreach ($pattern in $slimPatterns) {
		Get-ChildItem -LiteralPath $slimNodeModules -Recurse -Force -File -Filter $pattern -ErrorAction SilentlyContinue | ForEach-Object {
			# Keep .ts when there is no corresponding .js (rare but possible for some loaders).
			if ($_.Extension -eq ".ts") {
				$jsPath = [System.IO.Path]::ChangeExtension($_.FullName, ".js")
				if (-not (Test-Path -LiteralPath $jsPath)) { return }
			}
			try { [System.IO.File]::Delete($_.FullName) } catch {}
		}
	}
	$testDirs = Get-ChildItem -LiteralPath $slimNodeModules -Recurse -Force -Directory -ErrorAction SilentlyContinue |
		Where-Object { $_.Name -in @("test", "tests", "__tests__", "spec", "specs", "examples", "example", "docs", "doc") }
	foreach ($d in $testDirs) {
		try { Remove-Item -LiteralPath $d.FullName -Recurse -Force -ErrorAction SilentlyContinue } catch {}
	}
}

# Lean mode — drop tree-sitter WASMs for languages rarely used by Korean developers.
# These will simply fail to parse if loaded; tree-sitter handles missing wasm gracefully.
if ($Lean.IsPresent) {
	$leanWasm = @(
		"tree-sitter-tlaplus.wasm",
		"tree-sitter-systemrdl.wasm",
		"tree-sitter-rescript.wasm",
		"tree-sitter-elisp.wasm",
		"tree-sitter-ocaml.wasm",
		"tree-sitter-ql.wasm",
		"tree-sitter-elm.wasm",
		"tree-sitter-solidity.wasm",
		"tree-sitter-scala.wasm",
		"tree-sitter-embedded_template.wasm"
	)
	$distDir = Join-Path $extensionDir "dist"
	foreach ($w in $leanWasm) {
		$p = Join-Path $distDir $w
		if (Test-Path -LiteralPath $p) {
			try { [System.IO.File]::Delete($p); Write-Host "Lean: removed $w" } catch {}
		}
	}
}

$contentTypes = @'
<?xml version="1.0" encoding="utf-8"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
	<Default Extension="json" ContentType="application/json" />
	<Default Extension="vsixmanifest" ContentType="text/xml" />
	<Default Extension="txt" ContentType="text/plain" />
	<Default Extension="md" ContentType="text/markdown" />
	<Default Extension="png" ContentType="image/png" />
	<Default Extension="svg" ContentType="image/svg+xml" />
	<Default Extension="js" ContentType="application/javascript" />
	<Default Extension="css" ContentType="text/css" />
	<Default Extension="html" ContentType="text/html" />
	<Default Extension="wasm" ContentType="application/wasm" />
	<Default Extension="node" ContentType="application/octet-stream" />
	<Default Extension="ttf" ContentType="application/octet-stream" />
	<Default Extension="woff" ContentType="font/woff" />
	<Default Extension="woff2" ContentType="font/woff2" />
	<Default Extension="map" ContentType="application/json" />
</Types>
'@
[System.IO.File]::WriteAllText((Join-Path $stageRoot "[Content_Types].xml"), $contentTypes, $utf8NoBom)

$tags = ($package.keywords -join ",")
$categories = ($package.categories -join ",")
$homepage = if ($package.homepage) { $package.homepage } else { "" }
$repository = if ($package.repository.url) { $package.repository.url } else { $homepage }

$manifest = @"
<?xml version="1.0" encoding="utf-8"?>
<PackageManifest Version="2.0.0" xmlns="http://schemas.microsoft.com/developer/vsx-schema/2011" xmlns:d="http://schemas.microsoft.com/developer/vsx-schema-design/2011">
	<Metadata>
		<Identity Language="en-US" Id="$(Escape-Xml $package.name)" Version="$(Escape-Xml $package.version)" Publisher="$(Escape-Xml $package.publisher)" TargetPlatform="win32-x64" />
		<DisplayName>Vibe Code</DisplayName>
		<Description xml:space="preserve">$(Escape-Xml "AI-powered vibe coding assistant")</Description>
		<Tags>$(Escape-Xml $tags)</Tags>
		<Categories>$(Escape-Xml $categories)</Categories>
		<GalleryFlags>Public</GalleryFlags>
		<Properties>
			<Property Id="Microsoft.VisualStudio.Code.Engine" Value="$(Escape-Xml $package.engines.vscode)" />
			<Property Id="Microsoft.VisualStudio.Code.ExtensionDependencies" Value="" />
			<Property Id="Microsoft.VisualStudio.Code.ExtensionPack" Value="" />
			<Property Id="Microsoft.VisualStudio.Code.ExtensionKind" Value="workspace" />
			<Property Id="Microsoft.VisualStudio.Code.LocalizedLanguages" Value="en,ko" />
			<Property Id="Microsoft.VisualStudio.Code.EnabledApiProposals" Value="" />
			<Property Id="Microsoft.VisualStudio.Code.ExecutesCode" Value="true" />
			<Property Id="Microsoft.VisualStudio.Services.Links.Source" Value="$(Escape-Xml $repository)" />
			<Property Id="Microsoft.VisualStudio.Services.Links.Getstarted" Value="$(Escape-Xml $homepage)" />
			<Property Id="Microsoft.VisualStudio.Services.Links.Repository" Value="$(Escape-Xml $repository)" />
			<Property Id="Microsoft.VisualStudio.Services.Links.Learn" Value="$(Escape-Xml $homepage)" />
			<Property Id="Microsoft.VisualStudio.Services.Branding.Color" Value="$(Escape-Xml $package.galleryBanner.color)" />
			<Property Id="Microsoft.VisualStudio.Services.Branding.Theme" Value="$(Escape-Xml $package.galleryBanner.theme)" />
			<Property Id="Microsoft.VisualStudio.Services.GitHubFlavoredMarkdown" Value="true" />
			<Property Id="Microsoft.VisualStudio.Services.Content.Pricing" Value="Free" />
		</Properties>
		<License>extension/LICENSE.txt</License>
		<Icon>extension/assets/icons/icon.png</Icon>
	</Metadata>
	<Installation>
		<InstallationTarget Id="Microsoft.VisualStudio.Code" />
	</Installation>
	<Dependencies />
	<Assets>
		<Asset Type="Microsoft.VisualStudio.Code.Manifest" Path="extension/package.json" Addressable="true" />
		<Asset Type="Microsoft.VisualStudio.Services.Content.Details" Path="extension/readme.md" Addressable="true" />
		<Asset Type="Microsoft.VisualStudio.Services.Content.Changelog" Path="extension/changelog.md" Addressable="true" />
		<Asset Type="Microsoft.VisualStudio.Services.Content.License" Path="extension/LICENSE.txt" Addressable="true" />
		<Asset Type="Microsoft.VisualStudio.Services.Icons.Default" Path="extension/assets/icons/icon.png" Addressable="true" />
	</Assets>
</PackageManifest>
"@
[System.IO.File]::WriteAllText((Join-Path $stageRoot "extension.vsixmanifest"), $manifest, $utf8NoBom)
[System.IO.File]::WriteAllText((Join-Path $root ".vsixmanifest"), $manifest, $utf8NoBom)

$vsixPath = Join-Path $outDirFull "$($package.name)-$($package.version).vsix"
$zipTemp = "$vsixPath.zip"
if (Test-Path -LiteralPath $vsixPath) {
	Remove-Item -LiteralPath $vsixPath -Force
}
if (Test-Path -LiteralPath $zipTemp) {
	Remove-Item -LiteralPath $zipTemp -Force
}

Add-Type -AssemblyName System.IO.Compression.FileSystem
[System.IO.Compression.ZipFile]::CreateFromDirectory($stageRoot, $zipTemp, [System.IO.Compression.CompressionLevel]::Optimal, $false)
Move-Item -LiteralPath $zipTemp -Destination $vsixPath -Force

Write-Host "Created VSIX: $vsixPath"
param(
	[string]$VsixPath = ""
)

$ErrorActionPreference = "Stop"

function Fail([string]$Message) {
	Write-Error $Message
	exit 1
}

$root = [System.IO.Path]::GetFullPath((Join-Path $PSScriptRoot ".."))
$packagePath = Join-Path $root "package.json"
$package = Get-Content -LiteralPath $packagePath -Raw -Encoding UTF8 | ConvertFrom-Json
$errors = [System.Collections.Generic.List[string]]::new()
if (-not $VsixPath) { $VsixPath = "release\vibe-code-$($package.version).vsix" }

if ($package.name -ne "vibe-code") { $errors.Add("package.name must be vibe-code") }
if ($package.publisher -ne "vibe-code") { $errors.Add("package.publisher must be vibe-code") }
if ($package.version -notmatch "^[0-9]+\.[0-9]+\.[0-9]+$") { $errors.Add("package.version must be semver: $($package.version)") }
$vsixManifestPath = Join-Path $root ".vsixmanifest"
if (Test-Path -LiteralPath $vsixManifestPath) {
	$vsixManifest = Get-Content -LiteralPath $vsixManifestPath -Raw -Encoding UTF8
	if ($vsixManifest -notmatch ("Version=""" + [regex]::Escape($package.version) + """")) { $errors.Add(".vsixmanifest version must match package.json ($($package.version)); re-run scripts/package-vsix.ps1") }
}
if ($package.main -ne "./dist/extension.js") { $errors.Add("package.main must point to ./dist/extension.js") }

$activityBarId = $package.contributes.viewsContainers.activitybar[0].id
if ($activityBarId -ne "vibe-code-ActivityBar") { $errors.Add("activity bar id must be vibe-code-ActivityBar") }
if (-not $package.contributes.views."vibe-code-ActivityBar") { $errors.Add("views must be keyed by vibe-code-ActivityBar") }
if (-not ($package.contributes.views."vibe-code-ActivityBar" | Where-Object { $_.id -eq "vibe-code.GoalTracker" })) {
	$errors.Add("goal tracker view must be contributed in vibe-code-ActivityBar")
}
if (-not ($package.contributes.views."vibe-code-ActivityBar" | Where-Object { $_.id -eq "vibe-code.PlanBoard" })) {
	$errors.Add("plan board view must be contributed in vibe-code-ActivityBar")
}
if (-not ($package.contributes.views."vibe-code-ActivityBar" | Where-Object { $_.id -eq "vibe-code.GoalPlanMap" })) {
	$errors.Add("goal plan map view must be contributed in vibe-code-ActivityBar")
}

foreach ($command in $package.contributes.commands) {
	if (-not ([string]$command.command).StartsWith("vibe-code.")) {
		$errors.Add("command has wrong prefix: $($command.command)")
	}
}

$settings = $package.contributes.configuration.properties.PSObject.Properties
foreach ($setting in $settings) {
	if (-not ([string]$setting.Name).StartsWith("vibe-code.")) {
		$errors.Add("setting has wrong prefix: $($setting.Name)")
	}
}

$languageSetting = $package.contributes.configuration.properties."vibe-code.language"
if ($languageSetting.default -ne "ko") {
	$errors.Add("vibe-code.language default must be ko")
}

$commandIds = @($package.contributes.commands | ForEach-Object { $_.command })
$requiredCommands = @(
	"vibe-code.applyVibeCodersProxy",
	"vibe-code.restorePreviousProviderProfile",
	"vibe-code.showVibeCodersProxyStatus",
	"vibe-code.checkVibeCodersProxy",
	"vibe-code.writeVibeCodersProxyConfig",
	"vibe-code.openCurrentGoal",
	"vibe-code.showGoalStatus",
	"vibe-code.createGoalHandoff",
	"vibe-code.openLatestPlan",
	"vibe-code.advanceCurrentPlan",
	"vibe-code.setCurrentPlanStatus",
	"vibe-code.setCurrentPlanPriority",
	"vibe-code.linkCurrentPlanToGoal",
	"vibe-code.archiveDonePlans",
	"vibe-code.restoreArchivedPlan",
	"vibe-code.setActivePlan",
	"vibe-code.selectHighestPriorityPlan",
	"vibe-code.showPlanCatalog",
	"vibe-code.showPlanHistory",
	"vibe-code.showGoalPlanMap"
)
foreach ($command in $requiredCommands) {
	if (-not ($commandIds -contains $command)) {
		$errors.Add("missing required command: $command")
	}
}

$requiredSettings = @{
	"vibe-code.vibeCodersBaseUrl" = "http://localhost:8080/v1"
	"vibe-code.vibeCodersDefaultModel" = "gpt-4.1-mini"
	"vibe-code.vibeCodersProfileName" = "vibe-coders proxy"
}
foreach ($settingName in $requiredSettings.Keys) {
	$setting = $package.contributes.configuration.properties.$settingName
	if (-not $setting) {
		$errors.Add("missing required setting: $settingName")
	} elseif ($setting.default -ne $requiredSettings[$settingName]) {
		$errors.Add("$settingName default must be $($requiredSettings[$settingName])")
	}
}

$forbiddenPattern = "[Aa][Tt][Hh][Ee][Nn][Aa]|[Uu]racle"
$forbiddenGatewayPattern = (
	"startVibeCoders" + "Gateway|" +
	"openVibeCoders" + "Admin|" +
	"vibeCoders" + "AutoStart|" +
	"vibeCoders" + "ListenAddr|" +
	"vibeCoders" + "AdminUrl"
)
$scanTargets = @(
	"package.json",
	"package.nls.json",
	"package.nls.ko.json",
	"readme.md",
	"readme.ko.md",
	"changelog.md",
	"docs\README.md",
	"docs\source-analysis.md",
	"docs\maintenance-guide.md",
	"docs\improvement-roadmap.md",
	"docs\vibe-coders-proxy.md",
	"docs\autonomous-goal-workflow.md",
	"scripts\package-vsix.ps1",
	"scripts\verify-package.ps1",
	"scripts\smoke-vscode-cli.ps1",
	"scripts\test-extension-host.ps1",
	"scripts\run-extension-host-test.js",
	"tests\extension-host\index.js",
	"dist\extension.js",
	"dist\extension.core.js",
	"webview-ui\build\assets\index.js"
)

foreach ($relative in $scanTargets) {
	$path = Join-Path $root $relative
	if (Test-Path -LiteralPath $path) {
		$text = Get-Content -LiteralPath $path -Raw -Encoding UTF8
		if ($text -match $forbiddenPattern) {
			$errors.Add("stale branding found in $relative")
		}
		if ($text -match $forbiddenGatewayPattern) {
			$errors.Add("gateway-start integration should not be present in $relative")
		}
	}
}

$goalCommandFileName = "goal.md"
$goalCommandPath = Join-Path $root (Join-Path "assets\demo\.vibe\commands" $goalCommandFileName)
if (-not (Test-Path -LiteralPath $goalCommandPath)) {
	$errors.Add("missing Korean /goal slash command template")
} else {
	$goalCommandText = Get-Content -LiteralPath $goalCommandPath -Raw -Encoding UTF8
	if ($goalCommandText -notmatch "\.vibe-code/goals/current\.md") {
		$errors.Add("Korean /goal slash command must describe current goal state file")
	}
	if ($goalCommandText -notmatch "\.vibe-code/sessions/") {
		$errors.Add("Korean /goal slash command must describe session handoff files")
	}
}

$node = Get-Command node -ErrorAction SilentlyContinue
if ($node) {
	& node --check (Join-Path $root "dist\extension.js") | Out-Null
	if ($LASTEXITCODE -ne 0) { $errors.Add("dist/extension.js failed node --check") }
	& node --check (Join-Path $root "dist\extension.core.js") | Out-Null
	if ($LASTEXITCODE -ne 0) { $errors.Add("dist/extension.core.js failed node --check") }
	& node --check (Join-Path $root "webview-ui\build\assets\index.js") | Out-Null
	if ($LASTEXITCODE -ne 0) { $errors.Add("webview-ui/build/assets/index.js failed node --check") }
}

$extensionBundlePath = Join-Path $root "dist\extension.js"
$extensionBundle = Get-Content -LiteralPath $extensionBundlePath -Raw -Encoding UTF8
if ($extensionBundle -notmatch 'require\("\./extension\.core\.js"\)') {
	$errors.Add("dist/extension.js must load ./extension.core.js (run: npm run build)")
}
$coreBundlePath = Join-Path $root "dist\extension.core.js"
if (-not (Test-Path -LiteralPath $coreBundlePath)) {
	$errors.Add("dist/extension.core.js is missing (run: npm run build)")
} else {
	$coreBundle = Get-Content -LiteralPath $coreBundlePath -Raw -Encoding UTF8
	if ($coreBundle -notmatch "__vibeCode\?\.beforeCore") { $errors.Add("core bundle is missing the beforeCore hook (see vendor/PATCHES.md)") }
	if ($coreBundle -notmatch "__vibeCode\?\.mergeLocaleOverrides") { $errors.Add("core bundle is missing the mergeLocaleOverrides hook (see vendor/PATCHES.md)") }
	if (([regex]::Matches($coreBundle, "__vibeCode\?\.onCommand")).Count -ne 3) { $errors.Add("core bundle must call the onCommand hook at 3 sites (see vendor/PATCHES.md)") }
	if (([regex]::Matches($coreBundle, "__vibeCode\?\.onTask")).Count -ne 5) { $errors.Add("core bundle must call the onTask hook at 5 sites (see vendor/PATCHES.md)") }
